CREATE TABLE IF NOT EXISTS apple_chart_entry (country VARCHAR(2) NOT NULL, kind VARCHAR(16) NOT NULL, "rank" INT NOT NULL, appleId VARCHAR(64) NOT NULL, "name" TEXT NOT NULL, artistName TEXT NOT NULL, releaseDate VARCHAR(32) NULL, artworkUrl TEXT NULL, url TEXT NOT NULL, genres TEXT NOT NULL, isrc VARCHAR(32) NULL, upc VARCHAR(32) NULL, CONSTRAINT pk_apple_chart_entry PRIMARY KEY (country, kind, "rank"), CONSTRAINT chk_apple_chart_entry_signed_integer_rank CHECK ("rank" BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS apple_chart_fetch (country VARCHAR(2) NOT NULL, kind VARCHAR(16) NOT NULL, fetchedAt BIGINT NOT NULL, feedUpdatedAt BIGINT NOT NULL, CONSTRAINT pk_apple_chart_fetch PRIMARY KEY (country, kind));
